// ── 2) Bloc-to-bloc subscription ──
class NotificationsBloc extends Bloc<NotifEvent, NotifState> {
  NotificationsBloc(this.authBloc) : super(const NotifState.empty()) {
    on<NotifReceived>(_onReceived);
    // Subscribe to AuthBloc's stream
    _authSub = authBloc.stream.listen((authState) {
      if (authState is Anonymous) add(const ClearNotifs());
    });
  }
  final AuthBloc authBloc;
  late final StreamSubscription _authSub;

  @override
  Future<void> close() {
    _authSub.cancel();          // ✅ never leak the subscription
    return super.close();
  }
}

// ── 3) Shared repository — best decoupling ──
// Repository owns the source of truth; blocs subscribe to its stream.
class SessionRepository {
  final _ctrl = StreamController<Session?>.broadcast();
  Stream<Session?> get changes => _ctrl.stream;
  Session? _current;
  Session? get current => _current;

  Future<void> signIn(String email, String pwd) async {
    final s = await api.signIn(email, pwd);
    _current = s;
    _ctrl.add(s);
  }
  Future<void> signOut() async {
    await api.signOut();
    _current = null;
    _ctrl.add(null);
  }
  void dispose() => _ctrl.close();
}

