class CartState extends Equatable {
  const CartState({this.items = const []});
  final List<Item> items;

  CartState copyWith({List<Item>? items}) => CartState(items: items ?? this.items);

  @override
  List<Object?> get props => [items];   // ❌ miss a field here and emits vanish
}

class CartBloc extends Bloc<CartEvent, CartState> {
  CartBloc() : super(const CartState()) {
    on<ItemAdded>(_onAdded);
  }

  void _onAdded(ItemAdded e, Emitter<CartState> emit) {
    // ❌ mutates the existing list, emits the same state instance
    state.items.add(e.item);
    emit(state);

    // ✅ new list, new state object, different by ==
    emit(state.copyWith(items: [...state.items, e.item]));
  }
}

