// ── Option 1: the emitter owns the subscription ──
class OrdersBloc extends Bloc<OrdersEvent, OrdersState> {
  OrdersBloc(this._repo) : super(const OrdersLoading()) {
    on<OrdersWatchStarted>(_onWatch, transformer: restartable());
  }

  final OrdersRepository _repo;

  Future<void> _onWatch(OrdersWatchStarted e, Emitter<OrdersState> emit) {
    return emit.forEach<List<Order>>(
      _repo.watch(),
      onData: (orders) => OrdersLoaded(orders),
      onError: (error, _) => OrdersFailure(error.toString()),
    );
  }
}

// ── Option 3: the bloc owns the subscription, updates become events ──
class SessionBloc extends Bloc<SessionEvent, SessionState> {
  SessionBloc(this._auth) : super(const SessionUnknown()) {
    on<_UserChanged>((e, emit) {
      emit(e.user == null ? const SessionSignedOut() : SessionActive(e.user!));
    });
    _sub = _auth.userChanges().listen((u) => add(_UserChanged(u)));
  }

  final AuthRepository _auth;
  late final StreamSubscription<User?> _sub;

  @override
  Future<void> close() {
    _sub.cancel();          // ✅ cancel before the bloc goes away
    return super.close();
  }
}

class _UserChanged extends SessionEvent {
  const _UserChanged(this.user);
  final User? user;
}

