enum FeedStatus { initial, loading, ready, failure }

class FeedState extends Equatable {
  const FeedState({
    this.status = FeedStatus.initial,
    this.posts = const [],
    this.error,
    this.hasReachedEnd = false,
  });

  final FeedStatus status;
  final List<Post> posts;      // survives a refresh
  final String? error;
  final bool hasReachedEnd;

  FeedState copyWith({
    FeedStatus? status,
    List<Post>? posts,
    String? error,
    bool? hasReachedEnd,
  }) => FeedState(
        status: status ?? this.status,
        posts: posts ?? this.posts,
        error: error,
        hasReachedEnd: hasReachedEnd ?? this.hasReachedEnd,
      );

  @override
  List<Object?> get props => [status, posts, error, hasReachedEnd];
}

Future<void> _onRefresh(FeedRefreshed e, Emitter<FeedState> emit) async {
  emit(state.copyWith(status: FeedStatus.loading));   // list stays on screen
  try {
    final posts = await _repo.fetch();
    emit(state.copyWith(status: FeedStatus.ready, posts: posts));
  } catch (err) {
    // keep the old posts, surface the error next to them
    emit(state.copyWith(status: FeedStatus.failure, error: err.toString()));
  }
}

