// ❌ the effect is a plain field, so it survives into every later state
class FeedState extends Equatable {
  const FeedState({this.posts = const [], this.filter = Filter.all, this.message});
  final List<Post> posts;
  final Filter filter;
  final String? message;          // 'Saved' stays here forever
  @override
  List<Object?> get props => [posts, filter, message];
}

BlocListener<FeedBloc, FeedState>(
  listener: (context, state) {
    if (state.message != null) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(state.message!)));
    }
  },
  child: const FeedView(),
);
// change the filter -> new state, same message -> the snackbar is back

// ✅ consume it as soon as it has been shown
listener: (context, state) {
  final message = state.message;
  if (message == null) return;
  ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
  context.read<FeedBloc>().add(const MessageShown());   // handler emits message: null
},

// ✅ or stamp it, so two identical errors in a row still fire twice
class Effect extends Equatable {
  Effect(this.text) : id = _next++;
  static int _next = 0;
  final String text;
  final int id;
  @override
  List<Object?> get props => [text, id];
}

BlocListener<FeedBloc, FeedState>(
  listenWhen: (prev, curr) => curr.effect != null && prev.effect != curr.effect,
  listener: (context, state) => _showSnackBar(context, state.effect!.text),
  child: const FeedView(),
);

sealed class AuthEvent {}
final class LoggedIn extends AuthEvent {
  const LoggedIn(this.user);
  final User user;
}
final class LoggedOut extends AuthEvent {}

class AuthBloc extends Bloc<AuthEvent, AuthState> {
  AuthBloc(this._repo, this._analytics) : super(const AuthInitial()) {
    // ❌ "just for logging": it also matches LoggedIn, so both handlers run
    on<AuthEvent>((event, emit) => _analytics.log('$event'));
    on<LoggedIn>(_onLoggedIn);     // sign-in side effects now happen twice
    on<LoggedOut>(_onLoggedOut);

    // ❌ throws: on<LoggedIn> was called multiple times
    // on<LoggedIn>(_alsoOnLoggedIn);
  }

  final AuthRepository _repo;
  final Analytics _analytics;
}

// ✅ cross-cutting logging sits outside the handler pipeline
class LoggingObserver extends BlocObserver {
  @override
  void onEvent(Bloc bloc, Object? event) {
    super.onEvent(bloc, event);
    analytics.log('${bloc.runtimeType} $event');
  }
}

void main() {
  Bloc.observer = LoggingObserver();
  runApp(const App());
}

