void _onSavePressed(BuildContext context) {
  context.read<FormBloc>().add(const SaveTapped());
  if (context.read<FormBloc>().state.status == Status.success) {
    Navigator.of(context).pop();          // never true here
  }
}

// ✅ the listener is the callback you were trying to write
BlocConsumer<FormBloc, FormState>(
  listenWhen: (prev, curr) => prev.status != curr.status,
  listener: (context, state) {
    if (state.status == Status.success) Navigator.of(context).pop();
    if (state.status == Status.failure) _showError(context, state.error!);
  },
  builder: (context, state) => SaveButton(
    busy: state.status == Status.saving,
    onPressed: () => context.read<FormBloc>().add(const SaveTapped()),
  ),
);

// ✅ when the call site really needs a future, a cubit method says so
class DraftCubit extends Cubit<DraftState> {
  Future<bool> save() async {
    emit(state.copyWith(status: Status.saving));
    final ok = await _repo.save(state.draft);
    if (isClosed) return ok;
    emit(state.copyWith(status: ok ? Status.success : Status.failure));
    return ok;
  }
}

// inside a handler, emit updates state synchronously
on<SaveTapped>((event, emit) async {
  emit(state.copyWith(status: Status.saving));
  assert(state.status == Status.saving);  // true on this very line
  await _repo.save(state.draft);
});

