await expectLater(bloc.stream, emitsInOrder([isA<Saving>(), isA<Saved>()]));

class App extends StatelessWidget {
  const App({super.key});

  @override
  Widget build(BuildContext context) {
    return BlocBuilder<AuthBloc, AuthState>(
      buildWhen: (prev, curr) => prev.userId != curr.userId,
      builder: (context, auth) {
        if (auth.userId == null) return const LoginPage();
        return MultiBlocProvider(
          // ✅ the key is what forces a fresh element subtree per user;
