          key: ValueKey(auth.userId),
          providers: [
            BlocProvider(create: (c) => ProfileBloc(c.read<ProfileRepository>())),
            BlocProvider(create: (c) => CartBloc(c.read<CartRepository>())),
          ],
          child: const HomePage(),
        );
      },
    );
  }
}

// blocs that really must outlive the session need an explicit reset
class SessionBloc extends HydratedBloc<SessionEvent, SessionState> {
  SessionBloc(this._auth, this._caches) : super(const SessionUnknown()) {
    on<SignedOut>((event, emit) async {
      await _auth.signOut();
      for (final cache in _caches) {
        await cache.clear();                 // repository caches sit outside bloc
      }
      await HydratedBloc.storage.clear();    // and so does the persisted copy
      emit(const SessionSignedOut());
    });
  }

  final AuthRepository _auth;
  final List<Cache> _caches;
}

// ❌ snapshot rollback: undoes everything that happened during the request
Future<void> _onLiked(LikePressed e, Emitter<FeedState> emit) async {
  final previous = state;                       // the whole list, frozen
  emit(state.copyWith(posts: _patch(state.posts, e.id, (p) => p.copyWith(liked: true))));
  try {
    await _repo.like(e.id);
  } catch (_) {
    emit(previous);                             // also reverts other taps and a refresh
  }
}

// ✅ targeted edit, always applied to whatever the current state is
Future<void> _onLiked(LikePressed e, Emitter<FeedState> emit) async {
  emit(state.copyWith(
    posts: _patch(state.posts, e.id, (p) => p.copyWith(liked: true, pending: true)),
  ));
  try {
    final saved = await _repo.like(e.id, requestId: e.requestId);   // idempotent retry
    emit(state.copyWith(
      posts: _patch(state.posts, e.id, (_) => saved.copyWith(pending: false)),
    ));
  } catch (error) {
    emit(state.copyWith(
      posts: _patch(state.posts, e.id,
          (p) => p.copyWith(liked: false, pending: false, failed: true)),
      error: 'Could not save your like',
    ));
  }
}

List<Post> _patch(List<Post> posts, String id, Post Function(Post) edit) =>
    [for (final p in posts) if (p.id == id) edit(p) else p];

// one write at a time per entity; a second tap mid-flight is meaningless
on<LikePressed>(_onLiked, transformer: sequential());
